      SUBROUTINE ELTILTCC     STEPS THROUGH ELEMENT WHICH HAS NO FRINGE FIELDS BUT CAN C     BE ROLLEDCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, IMIS, IPTOJM(25), J, TYPEN      EXTERNAL        IDATACC     SEE IF ELEMENT IS ROTATEDC      TILT = IPTOJ(NTILT) .NE. 0      DMC = .FALSE.      BEFORE = .TRUE.CC     CHECK FOR MISALIGNMENTSC      IF (TYPE .EQ. 5 .AND. ALO(2)) THEN        NMIS = NM5        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100        RORC = MOD(TYT,10)        DMC = LFM .GE. 1      ENDIFCC     ENTRANCE MISALIGNMENTC      IF (DMC) THEN        TYPEC = 8        LXRAN = LFM .EQ. 2        DO 50 J = 1, 25   50   IPTOJB(J) = IPTOJ(J)        CALL SKETCH(NMIS)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200        DO 60 J = 1, 25        IPTOJM(J) = IPTOJ(J)   60   IPTOJ(J) = IPTOJB(J)      ENDIFCC     ROTATION OF ELEMENTC      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            SONLY = .TRUE.            CALL MPRINT            SONLY = .FALSE.          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFCC     MAIN ELEMENTC      TYPEC = TYPE      LXRAN = .TRUE.      IF (NV3 .GE. 1) THEN        CALL DERIVE      ELSE         CALL ELICIT        IF (.NOT. LSTEPN) THEN          CALL POSTER          CALL VPRINT          TYPEN = IDATA(ISTOR(NUM+NDIF))          IF (TILT .OR. (REFER .AND. TYPEN .EQ. 20)) SONLY = .TRUE.          CALL MPRINT          IF (TILT .OR. (REFER .AND. TYPEN .EQ. 20)) SONLY = .FALSE.        ENDIF      ENDIF      IF (FLUSHL) GO TO 200      IF (TYPE .LE. 0) GO TO 200CC     REVERSE ROTATION OF ELEMENTC      BEFORE = .FALSE.      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFCC     SEE IF ELEMENT IS MISALIGNEDC      DMC = .FALSE.      IF (TYPE .EQ. 5 .AND. ALO(2)) THEN        NMIS = NM5        DMC = .TRUE.      ENDIFCC     EXIT MISALIGNMENTC      IF (DMC) THEN        IF (NV3 .GE. 1) THEN          IF (LFM .EQ. 0 .AND. (R2P .OR. R3P)) CALL UPDAT2        ELSE          IF (LFM .EQ. 0 .AND. R2P) CALL UPDAT2        ENDIF        TYPEC = 8        DO 110 J = 1, 25  110   IPTOJ(J) = IPTOJM(J)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFC  200 RETURN      END